CREATE TABLE retail_contract_templates (id uuid PRIMARY KEY, company_id uuid NOT NULL, name text NOT NULL, body text NOT NULL, version bigint NOT NULL CHECK(version >= 1), created_by uuid NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE INDEX retail_contract_templates_company_idx ON retail_contract_templates(company_id, updated_at DESC);
CREATE TABLE retail_contract_versions (id uuid PRIMARY KEY, deal_id uuid NOT NULL REFERENCES retail_deals, company_id uuid NOT NULL, template_id uuid REFERENCES retail_contract_templates, template_version bigint, prior_signed_version_id uuid REFERENCES retail_contract_versions, kind text NOT NULL CHECK(kind IN ('contract','amendment')), state text NOT NULL CHECK(state IN ('draft','signed')), reference text NOT NULL DEFAULT '', signed_on date, file_ids jsonb NOT NULL DEFAULT '[]', content text NOT NULL, party_snapshot jsonb NOT NULL, terms_snapshot jsonb NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL, revision bigint NOT NULL CHECK(revision >= 1));
CREATE INDEX retail_contract_versions_deal_idx ON retail_contract_versions(company_id, deal_id, created_at, id);
INSERT INTO retail_contract_versions (id,deal_id,company_id,kind,state,reference,signed_on,file_ids,content,party_snapshot,terms_snapshot,created_by,created_at,revision) SELECT gen_random_uuid(),id,company_id,'contract','signed',contract_reference,contract_signed_on,contract_file_ids,'','{}','{}',created_by,updated_at,1 FROM retail_deals WHERE contract_signed_on IS NOT NULL;
